/* heat-3d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "heat-3d.h"

/* -----------------------------------------------------------------
 * Tunable blocking factors for the spatial dimensions.
 * They can be overridden at compile time, e.g.:
 *   gcc -DBLOCK_I=32 -DBLOCK_J=32 ...
 * -----------------------------------------------------------------*/
#ifndef BLOCK_I
#  define BLOCK_I 32
#endif

#ifndef BLOCK_J
#  define BLOCK_J 32
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		 DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int i, j, k;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++)
        A[i][j][k] = B[i][j][k] = (DATA_TYPE) (i + j + (n-k))* 10 / (n);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Hoist constant scalars (0.125 and 2.0) out of the loops.
   - Improve data locality with blocking in the i/j dimensions.
   - Use pointer-based traversal in the innermost (k) loop for
     contiguous memory access.
   - Reduce redundant loads of the center point.
   - Provide explicit vectorization hints for the k-loop.
   - Add OpenMP parallelization over the tiled i/j space (if
     compiled with -fopenmp; otherwise the pragmas are ignored).
 */
static
void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  /* Precompute scalar constants once. */
  const DATA_TYPE alpha = SCALAR_VAL(0.125);
  const DATA_TYPE beta  = SCALAR_VAL(2.0);

  /* Use PolyBench's "physical" size for correctness with possible
     padding or adjusted problem sizes. */
  const int ni      = _PB_N;
  const int i_start = 1;
  const int i_end   = ni - 1; /* exclusive upper bound: original was i < _PB_N-1 */
  const int j_start = 1;
  const int j_end   = ni - 1; /* exclusive */
  const int k_start = 1;
  const int k_end   = ni - 1; /* exclusive */

#pragma scop
  /* Time-stepping loop. We use the parameter tsteps so the kernel
     honors the value provided by the caller. */
  for (int t = 1; t <= tsteps; ++t) {

    /* ------------------------------------------------------------
     * First half-step: update B from A using a 7-point 3D stencil.
     * ----------------------------------------------------------*/
    #pragma omp parallel for collapse(2) schedule(static)
    for (int ii = i_start; ii < i_end; ii += BLOCK_I) {
      for (int jj = j_start; jj < j_end; jj += BLOCK_J) {

        const int i_max = (ii + BLOCK_I < i_end) ? (ii + BLOCK_I) : i_end;
        const int j_max = (jj + BLOCK_J < j_end) ? (jj + BLOCK_J) : j_end;

        for (int i = ii; i < i_max; ++i) {
          for (int j = jj; j < j_max; ++j) {

            /* Pointers to k-lines for this (i,j). They are declared
               inside the j-loop and are therefore private to each
               OpenMP iteration. */
            DATA_TYPE * restrict Bij   = &B[i][j][k_start];
            DATA_TYPE * restrict Aij   = &A[i][j][k_start];
            DATA_TYPE * restrict Aip1j = &A[i+1][j][k_start];
            DATA_TYPE * restrict Aim1j = &A[i-1][j][k_start];
            DATA_TYPE * restrict Aijp1 = &A[i][j+1][k_start];
            DATA_TYPE * restrict Aijm1 = &A[i][j-1][k_start];

            DATA_TYPE * restrict Bij_ptr   = Bij;
            DATA_TYPE * restrict Aij_ptr   = Aij;
            DATA_TYPE * restrict Aip1j_ptr = Aip1j;
            DATA_TYPE * restrict Aim1j_ptr = Aim1j;
            DATA_TYPE * restrict Aijp1_ptr = Aijp1;
            DATA_TYPE * restrict Aijm1_ptr = Aijm1;

            /* Innermost loop: contiguous traversal in k.
               We only read from A and write to B, so there are no
               loop-carried true dependencies; this loop is safe to
               vectorize. */
            #pragma GCC ivdep
            for (int k = k_start; k < k_end; ++k) {

              const DATA_TYPE center     = *Aij_ptr;
              const DATA_TYPE neg2center = -beta * center;

              /* Keep the arithmetic structure close to the original
                 expression, but reuse -2.0 * center across the three
                 directions to reduce work. */
              const DATA_TYPE acc_x =
                  *Aip1j_ptr + neg2center + *Aim1j_ptr;
              const DATA_TYPE acc_y =
                  *Aijp1_ptr + neg2center + *Aijm1_ptr;
              const DATA_TYPE acc_z =
                  Aij_ptr[1]  + neg2center + Aij_ptr[-1];

              *Bij_ptr = center
                       + alpha * acc_x
                       + alpha * acc_y
                       + alpha * acc_z;

              ++Bij_ptr;
              ++Aij_ptr;
              ++Aip1j_ptr;
              ++Aim1j_ptr;
              ++Aijp1_ptr;
              ++Aijm1_ptr;
            }
          }
        }
      }
    }

    /* ------------------------------------------------------------
     * Second half-step: update A from B (same stencil, swapped
     * roles of A and B).
     * ----------------------------------------------------------*/
    #pragma omp parallel for collapse(2) schedule(static)
    for (int ii = i_start; ii < i_end; ii += BLOCK_I) {
      for (int jj = j_start; jj < j_end; jj += BLOCK_J) {

        const int i_max = (ii + BLOCK_I < i_end) ? (ii + BLOCK_I) : i_end;
        const int j_max = (jj + BLOCK_J < j_end) ? (jj + BLOCK_J) : j_end;

        for (int i = ii; i < i_max; ++i) {
          for (int j = jj; j < j_max; ++j) {

            DATA_TYPE * restrict Aij   = &A[i][j][k_start];
            DATA_TYPE * restrict Bij   = &B[i][j][k_start];
            DATA_TYPE * restrict Bip1j = &B[i+1][j][k_start];
            DATA_TYPE * restrict Bim1j = &B[i-1][j][k_start];
            DATA_TYPE * restrict Bijp1 = &B[i][j+1][k_start];
            DATA_TYPE * restrict Bijm1 = &B[i][j-1][k_start];

            DATA_TYPE * restrict Aij_ptr   = Aij;
            DATA_TYPE * restrict Bij_ptr   = Bij;
            DATA_TYPE * restrict Bip1j_ptr = Bip1j;
            DATA_TYPE * restrict Bim1j_ptr = Bim1j;
            DATA_TYPE * restrict Bijp1_ptr = Bijp1;
            DATA_TYPE * restrict Bijm1_ptr = Bijm1;

            #pragma GCC ivdep
            for (int k = k_start; k < k_end; ++k) {

              const DATA_TYPE center     = *Bij_ptr;
              const DATA_TYPE neg2center = -beta * center;

              const DATA_TYPE acc_x =
                  *Bip1j_ptr + neg2center + *Bim1j_ptr;
              const DATA_TYPE acc_y =
                  *Bijp1_ptr + neg2center + *Bijm1_ptr;
              const DATA_TYPE acc_z =
                  Bij_ptr[1]  + neg2center + Bij_ptr[-1];

              *Aij_ptr = center
                       + alpha * acc_x
                       + alpha * acc_y
                       + alpha * acc_z;

              ++Aij_ptr;
              ++Bij_ptr;
              ++Bip1j_ptr;
              ++Bim1j_ptr;
              ++Bijp1_ptr;
              ++Bijm1_ptr;
            }
          }
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_heat_3d (tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
