/* ---------------------------------------------------------------------
 * Tunable blocking factors for the (i,j) dimensions.
 *
 * These control the 2D tiling used in the main kernel to improve
 * cache locality. They can be adjusted at compile time, e.g.:
 *
 *   -DHEAT3D_BLOCK_I=32 -DHEAT3D_BLOCK_J=16
 *
 * The chosen defaults are conservative and intended to work well
 * on a wide range of hardware.
 * ------------------------------------------------------------------- */
#ifndef HEAT3D_BLOCK_I
# define HEAT3D_BLOCK_I 32
#endif

#ifndef HEAT3D_BLOCK_J
# define HEAT3D_BLOCK_J 32
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		 DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
