  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++)
        A[i][j][k] = B[i][j][k] = (DATA_TYPE) (i + j + (n-k))* 10 / (n);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - Use the runtime parameter tsteps instead of the macro TSTEPS.
 *    (main passes TSTEPS as tsteps, so this preserves program behavior.)
 *  - 2D blocking in (i,j) using HEAT3D_BLOCK_I/J to improve cache locality.
 *  - OpenMP parallelization over the spatial domain for each time step,
 *    with a single parallel region encompassing the whole time loop.
 *  - Inner-most k-loop is kept contiguous in memory and vectorized
 *    via '#pragma omp simd'.
 *  - The stencil formula is algebraically simplified:
 *        new = A[i][j][k]
 *              + 0.125 * [ (A[i+1] - 2*A[i] + A[i-1]) +
 *                          (A[j+1] - 2*A[i] + A[j-1]) +
 *                          (A[k+1] - 2*A[i] + A[k-1]) ]
 *      becomes
 *        new = 0.25 * center + 0.125 * sum_of_6_neighbors
 *    which is mathematically equivalent but uses fewer arithmetic
 *    operations and memory reads.
 */
static
void __attribute__((flatten, noinline))
kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  /* Precompute constants once; SCALAR_VAL ensures correct DATA_TYPE. */
  const DATA_TYPE w_center  = SCALAR_VAL(0.25);   /* weight for center point */
  const DATA_TYPE w_neighbor = SCALAR_VAL(0.125); /* weight for each neighbor */

  /* NOTE: We use _PB_N (PolyBench's "parameterized N") for loop bounds,
     as in the original code, to preserve its behavior and any relation
     between 'n' and '_PB_N' established by the PolyBench macros. */

#pragma scop
  /* Single parallel region for all time steps to amortize OpenMP
     startup costs. Variables n, tsteps, A, B, etc. are shared by
     default. */
#pragma omp parallel
  {
    for (int t = 1; t <= tsteps; t++) {

      /* ----------------------------------------------------------------
       * First sweep: update B from A
       *
       * We block the (i,j) dimensions to improve spatial locality in
       * all three dimensions. The inner-most k-loop traverses the
       * last dimension, which is contiguous in memory for
       * A[i][j][k] / B[i][j][k].
       * ---------------------------------------------------------------- */
#pragma omp for collapse(2) schedule(static)
      for (int ii = 1; ii < _PB_N-1; ii += HEAT3D_BLOCK_I) {
        for (int jj = 1; jj < _PB_N-1; jj += HEAT3D_BLOCK_J) {

          /* Handle edge tiles where the remaining extent may be
             smaller than the block size. */
          const int i_end = (ii + HEAT3D_BLOCK_I < _PB_N-1) ?
                            (ii + HEAT3D_BLOCK_I) : (_PB_N-1);
          const int j_end = (jj + HEAT3D_BLOCK_J < _PB_N-1) ?
                            (jj + HEAT3D_BLOCK_J) : (_PB_N-1);

          for (int i = ii; i < i_end; i++) {
            for (int j = jj; j < j_end; j++) {
              /* k-loop is perfectly vectorizable: no loop-carried
                 dependencies and accesses are unit-stride. */
#pragma omp simd
              for (int k = 1; k < _PB_N-1; k++) {
                const DATA_TYPE center = A[i][j][k];

                /* Sum the 6 axis-aligned neighbors of the current
                   grid point. This matches the original stencil. */
                const DATA_TYPE sum_neighbors =
                    A[i+1][j][k] + A[i-1][j][k] +
                    A[i][j+1][k] + A[i][j-1][k] +
                    A[i][j][k+1] + A[i][j][k-1];

                /* Algebraically equivalent to the original expression:
                   B = A + 0.125 * [ (A_ip1 - 2*A + A_im1) +
                                    (A_jp1 - 2*A + A_jm1) +
                                    (A_kp1 - 2*A + A_km1) ]
                     = 0.25 * A + 0.125 * sum_neighbors
                   This reduces the number of multiplications and
                   repeated loads of A[i][j][k]. */
                B[i][j][k] = w_center * center +
                             w_neighbor * sum_neighbors;
              }
            }
          }
        }
      }

      /* ----------------------------------------------------------------
       * Second sweep: update A from B
       *
       * Same structure and blocking as the first sweep, but with the
       * roles of A and B swapped.
       * ---------------------------------------------------------------- */
#pragma omp for collapse(2) schedule(static)
      for (int ii = 1; ii < _PB_N-1; ii += HEAT3D_BLOCK_I) {
        for (int jj = 1; jj < _PB_N-1; jj += HEAT3D_BLOCK_J) {

          const int i_end = (ii + HEAT3D_BLOCK_I < _PB_N-1) ?
                            (ii + HEAT3D_BLOCK_I) : (_PB_N-1);
          const int j_end = (jj + HEAT3D_BLOCK_J < _PB_N-1) ?
                            (jj + HEAT3D_BLOCK_J) : (_PB_N-1);

          for (int i = ii; i < i_end; i++) {
            for (int j = jj; j < j_end; j++) {
#pragma omp simd
              for (int k = 1; k < _PB_N-1; k++) {
                const DATA_TYPE center = B[i][j][k];

                const DATA_TYPE sum_neighbors =
                    B[i+1][j][k] + B[i-1][j][k] +
                    B[i][j+1][k] + B[i][j-1][k] +
                    B[i][j][k+1] + B[i][j][k-1];

                A[i][j][k] = w_center * center +
                             w_neighbor * sum_neighbors;
              }
            }
          }
        }
      }

      /* Implicit barrier at the end of each 'omp for' ensures that:
         - all B-values are computed before any thread starts using B
           to update A in this time step;
         - all A-values are computed before proceeding to the next
           time step. This preserves the original sequential semantics. */
    } /* end of time-stepping loop */
  } /* end of parallel region */
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_heat_3d (tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
